from moler.util.moler_test import MolerTest
from taf.ul.sc.uesim.generic_controller import GenericController


class Controller(GenericController):
    def __init__(self,
                 device_name='RTG1_CONSOLE',  # type: 'Optional[str]'
                 device=None,  # type: 'Optional[RtgController]'
                 autoconnect=True,  # type: 'Optional[bool]'
                 get_device=False  # type: 'Optional[bool]'
                 ):
        super(Controller, self).__init__(device_name=device_name, device=device,
                                         autoconnect=autoconnect, get_device=get_device)

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect_to_dsp(self, dsp_number):
        """
        Connect to dsp.
        :return: None
        """
        self.device.goto_state(state="DSP{}".format(dsp_number))

        MolerTest.steps_end()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def return_to_ctrl(self):
        """
        Reconnect to controller.
        :return: None
        """
        self.device.goto_state(state="LINUX")

        MolerTest.steps_end()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def reboot_controller(self, timeout=600):
        """
        Reboot Controller.
        Works only with controller via telnet.
        :return: None
        """
        self.device.goto_state(self.basic_state)

        enter_cmd = self.device.get_cmd(cmd_name="enter")
        enter_cmd()

        sync_cmd = self.device.get_cmd(cmd_name="sync")
        sync_cmd()

        reboot_event = self.device.get_event(event_name="parouter_closed", event_params={"till_occurs_times": 1})
        reboot_event.start()

        reboot_cmd = self.device.get_cmd(cmd_name="reboot")
        reboot_cmd(timeout=timeout)

        reboot_event.await_done(timeout=timeout)

        self.device.goto_state(self.device.unix_local)
        self.device.goto_state(self.device.linux)

        MolerTest.steps_end()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def run_dsp_command(self, dsp_number, dsp_command, timeout=10):
        self.connect_to_dsp(dsp_number)
        dsp_command = self.device.get_cmd(cmd_name="run_dsp_command", cmd_params={"dsp_command": dsp_command})
        result = dsp_command(timeout)
        self.return_to_ctrl()

        MolerTest.steps_end()
        return result['LINES']
